package io.payflow.common;

/** Builds the PaymentAuthorized payload (schemas/PaymentAuthorized.json). No poison field: healthy events only. */
public final class PaymentPayload {
    private PaymentPayload() {
    }

    /** Compact JSON. Ids are generated by the apps (hex/uuid/m-NNN), so no escaping is needed. */
    public static String authorized(String paymentId, String merchantId, long amountMinor) {
        return "{\"payment_id\":\"" + paymentId + "\",\"merchant_id\":\"" + merchantId
                + "\",\"amount_minor\":" + amountMinor + ",\"currency\":\"USD\"}";
    }
}
